script language=javascript
function focusUsername()
{
document.getElementById(username).focus();
// encode the hash so it will work in IE
var hash = window.location.hash;
if(hash)
{
/* This causes the window to load 2 times, but it is the easiest way to get around IE&apos;s problem.
* If we want to fix it without a double load, we might be able to pass the hash fragment as
* another parameter to login.cgi and change the redirect there.
*/
window.location.href = window.location.href.substr(0, window.location.href.indexOf(&apos;#&apos;)) + encodeURIComponent(hash);
}


}

function checkUserSession()
{
SF.Modal.get(&apos;confirm_dialog&apos;).show();
}

function add_dynamic_input( name, val )
{
var dynamicInput = document.createElement(INPUT);
dynamicInput.type = hidden;
dynamicInput.name = name;
dynamicInput.value = val;
document.forms[0].appendChild( dynamicInput );
}

function submitForm( submit, add_continue, ask_clear )
{


var username = document.getElementById(&apos;username&apos;).value;
var VAE_EDITED_TEXT = document.getElementById(&apos;VAE_EDITED_TEXT&apos;).value;

if (add_continue)
{
add_dynamic_input(logon,Continue);
}

if(submit || username ==  || VAE_EDITED_TEXT == )
{
document.forms[0].submit();
}
else if(!document.getElementById(&apos;login_button&apos;).disabled)
{
if (!ask_clear) 
{
add_dynamic_input(logon_alt,askToClearSession);
}
document.forms[0].submit();
}
return false;
}




